h.sin(state.orient.pitch); state.vel.x+=Math.cos(state.orient.yaw)*forward*thrust*dt; state.vel.z+=Math.sin(state.orient.yaw)*forward*thrust*dt; state.vel.y+=vertical*thrust*dt - GRAVITY*dt; // apply G-force limit // INSTRUMENT LAG DURING HIGH G-FORCES (Intentional bug) const gForce=Math.abs(state.vel.y)/GRAVITY; if(gForce>G_FORCE_LIMIT){ display.lagTimer+=dt; if(display.lagTimer>0.2){display.lagTimer=0; display.speed=state.actualSpeed; display.altitude=state.actualAltitude; display.heading=state.actualHeading;} }else{display.speed=state.actualSpeed;display.altitude=state.actualAltitude;display.heading=state.actualHeading;display.lagTimer=0;} // update position state.pos.x+=state.vel.x*dt; state.pos.y+=state.vel.y*dt; state.pos.z+=state.vel.z*dt; // update actual readings state.actualSpeed=Math.sqrt(state.vel.x*state.vel.x+state.vel.y*state.vel.y+state.vel.z*state.vel.z); state.actualAltitude=state.pos.y; state.actualHeading=(state.orient.yaw*180/Math.PI)%360; if(state.actualHeading<0)state.actualHeading+=360; // ALTIMETER STICKINESS AT CERTAIN ALTITUDES (Intentional bug) const altitudeBand=Math.floor(state.actualAltitude/1000); if(state.actualAltitude%1000<20 && !display.altStuck){display.altStuck=true;display.altStickTimer=0;} if(display.altStuck){display.altStickTimer+=dt; if(display.altStickTimer>1){display.altStuck=false;}} if(display.altStuck){display.altitude=altitudeBand*1000;} // COMPASS DEVIATION NEAR MAGNETIC ANOMALIES (Intentional bug) const anomalyZone=Math.abs(state.pos.x)%5000<200 && Math.abs(state.pos.z)%5000<200; if(anomalyZone){display.compassError=Math.sin(Date.now()*0.001)*5; }else{display.compassError=0;} // consume fuel if(state.fuel>0){state.fuel-=state.throttle*dt*0.5;}else{state.fuel=0; state.throttle=0;} }function draw(){ctx.clearRect(0,0,canvas.width,canvas.height); // SKY & GROUND // Horizon based on pitch // Simple perspective: horizon y = canvas.height/2 - pitch*scale const scale=200; const horizonY=canvas.height/2 - state.orient.pitch*scale; // roll tilt const rollSin=Math.sin(state.orient.roll); const rollCos=Math.cos(state.orient.roll); // draw sky ctx.fillStyle='#87CEEB'; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(canvas.width,0); ctx.lineTo(canvas.width, horizonY); ctx.lineTo(0, horizonY); ctx.closePath(); ctx.fill(); // draw ground ctx.fillStyle='#654321'; ctx.beginPath(); ctx.moveTo(0,horizonY); ctx.lineTo(canvas.width,horizonY); ctx.lineTo(canvas.width,canvas.height); ctx.lineTo(0,canvas.height); ctx.closePath(); ctx.fill(); // simple terrain line (optional) ctx.strokeStyle='#228B22'; ctx.beginPath(); for(let x=0;x<canvas.width;x+=5){ const worldX=(x-canvas.width/2)/scale; const height=Math.sin((state.pos.x+worldX*50)/200)*20; const screenY=horizonY+height; ctx.lineTo(x,screenY); } ctx.stroke(); // HUD background ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(0,canvas.height-80,canvas.width,80); ctx.fillStyle='white'; ctx.font='14px monospace'; // speed let speedText='SPD:'+Math.round(display.speed)+' km/h'; if(display.lagTimer>0){speedText+=' *';} ctx.fillText(speedText,10,canvas.height-60); // altitude let altText='ALT:'+Math.round(display.altitude)+' m'; if(display.altStuck){altText+=' *';} ctx.fillText(altText,150,canvas.height-60); // heading let hdg=Math.round(display.heading+display.compassError)%360; if(hdg<0)hdg+=360; let headingText='HDG:'+hdg+'°'; if(display.compassError!==0){headingText+=' *';} ctx.fillText(headingText,290,canvas.height-60); // fuel let fuelText='FUEL:'+Math.round(state.fuel)+'%'; if(display.engineFluct!==0){fuelText+=' *';} ctx.fillText(fuelText,430,canvas.height-60); // throttle indicator ctx.fillStyle='white'; ctx.fillRect(10,canvas.height-30,100,20); ctx.fillStyle='green'; ctx.fillRect(10,canvas.height-30,100*state.throttle,20); ctx.strokeStyle='white'; ctx.strokeRect(10,canvas.height-30,100,20); ctx.fillStyle='white'; ctx.font='12px monospace'; ctx.fillText('Throttle',115,canvas.height-15); }function loop(timestamp){const dt=(timestamp-lastTime)/1000; lastTime=timestamp; update(dt); draw(); requestAnimationFrame(loop); }requestAnimationFrame(loop);}

